package decisions

import (
	"encoding/json"
	"os"
	"strings"
	"testing"

	"github.com/anyweez/cairn/codec"
	"go.yaml.in/yaml/v3"
)

// The manifest is generated by cmd/cairn-manifest from source. This checks it
// against the codecs the program actually builds, so an upcaster that never
// runs, or a registration taken as a function value and missed, fails here
// rather than when an entry already in a ledger is decoded.
func TestCodecsMatchManifest(t *testing.T) {
	t.Parallel()
	raw, err := os.ReadFile("../../spec.manifest.yaml")
	if err != nil {
		t.Fatal(err)
	}
	var m struct {
		Codecs []struct {
			Sum     string `yaml:"sum"`
			Name    string `yaml:"name"`
			Version int    `yaml:"version"`
			Upcasts []int  `yaml:"upcasts"`
		} `yaml:"codecs"`
	}
	if err := yaml.Unmarshal(raw, &m); err != nil {
		t.Fatalf("reading spec.manifest.yaml: %v", err)
	}
	want := make([]codec.Registration, len(m.Codecs))
	for i, c := range m.Codecs {
		want[i] = codec.Registration{Sum: c.Sum, Name: c.Name, Version: c.Version, Upcasts: c.Upcasts}
	}
	if problems := codec.CheckRegistrations(want, Codecs().Registrations()); len(problems) > 0 {
		t.Fatalf("spec.manifest.yaml and the built codecs disagree:\n  %s", strings.Join(problems, "\n  "))
	}
}

// IndexReferences went from naming the decision's text to naming the rows that
// hold it, so its version went up. An effect stored before that still has to
// decode: the upcaster keeps the old text as the title's reference, which is
// the only place it can go once the ledger no longer holds the words.
func TestAnOlderIndexEffectStillDecodes(t *testing.T) {
	t.Parallel()
	env := codec.Envelope{Type: "decision.index_references", Version: 1,
		Data: json.RawMessage(`{"decision":"d-1","text":"ship it?\nthe bugs are cosmetic"}`)}
	got, err := Codecs().Effects.Decode(env)
	if err != nil {
		t.Fatal(err)
	}
	want := IndexReferences{Decision: "d-1", Title: Ref("ship it?\nthe bugs are cosmetic")}
	if got != want {
		t.Fatalf("decoded %+v, want %+v", got, want)
	}
}
